    <style>
        /*
  Self-hosted, base64-embedded fonts (Fontsource's Archivo/Source Sans 3
  packages, OFL-licensed — same font files Google Fonts serves, just
  vendored locally instead of fetched over the network on every single
  PDF render). This was the single biggest, most variable source of
  render-time latency: Chrome had to wait on a real HTTP round-trip to
  fonts.googleapis.com before it could finish painting the page, and
  that round-trip's latency is exactly what made some renders feel fast
  and others slow. Zero network calls now — render time depends only on
  Chrome's own startup + layout, which is fast and consistent.
*/
        @font-face {
            font-family: 'Archivo';
            font-style: normal;
            font-weight: 700;
            font-display: block;
            src: url(data:font/woff2;base64,) format('woff2');
        }

        @font-face {
            font-family: 'Archivo';
            font-style: normal;
            font-weight: 800;
            font-display: block;
            src: url(data:font/woff2;base64,) format('woff2');
        }

        @font-face {
            font-family: 'Archivo';
            font-style: normal;
            font-weight: 900;
            font-display: block;
            src: url(data:font/woff2;base64,) format('woff2');
        }

        @font-face {
            font-family: 'Source Sans 3';
            font-style: normal;
            font-weight: 400;
            font-display: block;
            src: url(data:font/woff2;base64,) format('woff2');
        }

        @font-face {
            font-family: 'Source Sans 3';
            font-style: normal;
            font-weight: 600;
            font-display: block;
            src: url(data:font/woff2;base64,) format('woff2');
        }
    </style>
